import {CommonModal} from '../../common/game-core/components/CommonModal';
import {openCommonModalInScene} from '../../common/game-core';
import {SceneEvents} from '../../common';
import {IGameEvents} from '../events';
import {createViewSettings} from '../auto_generated/tuned';
import {addButtonInteractivity, ButtonEvents} from '../auto_generated/addButtonViewInteractivity';
import {IGameConfig} from '../../logic';
import {addGeneratedButtonSounds} from '../auto_generated/tuned/utils.tuned';

interface IProps {
    scene: Phaser.Scene;
    gameConfig: IGameConfig
}

/**
 * Простая обертка для диалога по этому образцу строй остальные
 * - конструктор - кэшируем создание которое можно кэшировть, подписки
 * - openDialog
 * - createDialog
 *
 * Фокусируй диалоги таким образом - обработчик и создатель в одном файле!
 * ViewElementBuilder должен хранить простые хелперы
 *
 * наследование от Zone сделано для совместимости очистки на destroy
 * **/
export class SpiderSettingsDialogManager extends Phaser.GameObjects.Zone {
    private readonly sceneEvents: SceneEvents<IGameEvents>;

    constructor(private readonly props: IProps) {
        super(props.scene, 0, 0);
        this.sceneEvents = new SceneEvents<IGameEvents>({scene: props.scene});
        this.sceneEvents.on("onSettingsButtonClick", () => {
            this.openDialog();
        });
    }

    destroy(fromScene?: boolean) {
        this.sceneEvents.unSubscribeAll();
        super.destroy(fromScene);
    }

    openDialog() {
        const {scene, gameConfig} = this.props;
        const animationDuration = gameConfig.dialogs?.animationShowDuration ?? 180;
        /** запускаем диалог в новой сцене **/
        openCommonModalInScene({
            parentScene: scene,
            createContent: (scene) => this.createDialog(scene),
            props: {
                animationDuration,
                isCloseOnOverlayClick: true
            },
        });
    }

    createDialog(scene: Phaser.Scene) {
        const {scene: parentScene} = this.props;

        /** интерактив для этой сцены **/
        addButtonInteractivity(scene);
        addGeneratedButtonSounds(scene);

        const modalSceneEvents = new SceneEvents<IGameEvents>({scene});
        const onButtonCloseClick = ({gameObjectName}: { gameObjectName: string }) => {
            if (gameObjectName !== "buttonBack") {
                return;
            }
            scene.events.emit(CommonModal.EVENT_CLOSE_COMMAND);
        };

        /** view-settings живет в modal scene, поэтому настройки вручную синхронизируем с parent scene. */
        modalSceneEvents.on("gameSettingsUpdated", (settings) => {
            parentScene.events.emit("gameSettingsUpdated", settings);
        });
        scene.events.on(ButtonEvents.onClick, onButtonCloseClick);
        scene.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
            modalSceneEvents.unSubscribeAll();
            scene.events.off(ButtonEvents.onClick, onButtonCloseClick);
        });

        return createViewSettings({scene});
    }
}
