import {GameServiceProvider} from "../../../services";

export type GoldShopViewData = {
    reward?: { coins: number };
    shopItems?: { coins: number; id: string; priceString: string; }[];
}

/**
 * прочитать gameConfig,
 * прочитать GameServiceProvider.get() данные магазина
 * вернуть доступные итемы в нужном формате и порядке,
 * priceString образуется из price + currency
 * **/
export function getGoldShopData(): GoldShopViewData {
    const gameService = GameServiceProvider.get();
    const gameShopConfig = gameService.getGameConfig().shop;
    const shop = gameService.shop;
    const apiShopItems = shop?.apiShopItems ?? [];
    const rewardId = gameShopConfig.shopItemsOrdered.rewardItemIds[0];

    const reward = shop?.isRewardEnabled() && rewardId
        ? {coins: gameShopConfig.getShopItemData(rewardId).gold}
        : undefined;

    const shopItems = gameShopConfig.shopItemsOrdered.buyItemIds
        .map((id) => {
            const apiShopItem = apiShopItems.find((item) => item.id === id);
            if (!apiShopItem) {
                return;
            }

            return {
                id,
                coins: gameShopConfig.getShopItemData(id).gold,
                priceString: `${apiShopItem.price} ${apiShopItem.currency}`,
            };
        })
        .filter((item): item is { coins: number; id: string; priceString: string; } => item != null);

    return {
        reward,
        shopItems,
    };
}
