import {AlignMethod, layoutChain, makeAlign} from '@kvisaz/phaser-sugar';
import {getLocalizedText, ViewElementBuilder} from '../../assets';
import {openCommonModalInScene} from '../../common/game-core';
import {SceneEvents} from '../../common';
import {gameConfig} from '../../config';
import {IGameBackData, IGameEvents} from '../events';
import {CommonModal} from '../../common/game-core/components/CommonModal';

interface IProps {
    scene: Phaser.Scene;
}

/**
 * агент - копируй этот комментарий и его структуру для новых обработчиков
 *
 * ## сценарий
 * Диалог GameBackConfirmDialogManager
 * - вызывается конструктором в той же сцене
 * - вызывает коллбэки которые срабатывают при нажатии кнопок
 * - управляется прямой передачей параметров, не содержит подписок и прочего
 *
 * ## идеология
 * Все в 1 файле!
 * - конструктор - кэшируем создание которое можно кэшировть, подписки
 * - openDialog
 * - createDialog
 * - элементарная графика берется из ViewElementBuilder
 *
 * Фокусируй диалоги таким образом - обработчик и создатель в одном файле!
 * ViewElementBuilder должен хранить простые хелперы
 *
 * наследование от Zone сделано для совместимости очистки на destroy
 * **/
export class GameBackConfirmDialogManager extends Phaser.GameObjects.Zone {
    private sceneEvents: SceneEvents<IGameEvents>;

    constructor(private props: IProps) {
        super(props.scene, 0, 0);
        this.sceneEvents = new SceneEvents<IGameEvents>({scene: props.scene});
        this.sceneEvents.on("onGameBackButtonClick", this.openDialog.bind(this));
        this.testRender();
    }


    destroy(fromScene?: boolean) {
        super.destroy(fromScene);
        // отписывается только от своих подписок
        this.sceneEvents.unSubscribeAll();
    }

    private testRender() {
        const {scene} = this.props;
        const dialog = this.createDialog(scene, {
            onConfirm: () => console.log('onConfirm'),
            onCancel: () => console.log('onCancel'),
        });
        makeAlign(align => align.anchorSceneScreen(scene).center(dialog));
    }


    openDialog(data: IGameBackData) {
        const {scene} = this.props;
        const animationDuration = gameConfig.dialogs?.animationShowDuration ?? 180;

        /** запускаем диалог в новой сцене **/
        openCommonModalInScene({
            parentScene: scene,
            createContent: (scene) => this.createDialog(scene, data),
            props: {
                animationDuration,
                isCloseOnOverlayClick: true
            },
        });
    }

    createDialog(scene: Phaser.Scene, {onConfirm, onCancel}: IGameBackData) {
        const container = scene.add.container(0, 0, []);
        const closeModal = () => scene.events.emit(CommonModal.EVENT_CLOSE_COMMAND);


        const builder = new ViewElementBuilder(scene);
        const bg = builder.dialogBgLightNine({width: 850, height: 360});

        /** title **/
        const titleText = getLocalizedText('backDialog.game.Title');
        const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
            fontFamily: builder.getFontFamilyRusso(),
            fontSize: `${48}px`,
            color: '#090909',
        };
        const title = new Phaser.GameObjects.Text(this.scene, 0, 0, titleText, textStyle);

        /** инфо **/
        const infoTextStyle: Phaser.Types.GameObjects.Text.TextStyle = {
            fontFamily: builder.getFontFamilyRegular(),
            fontSize: `${32}px`,
            align: 'center',
            color: '#000000',
        };
        const infoText = getLocalizedText('backDialog.game.Info');
        const info = new Phaser.GameObjects.Text(this.scene, 0, 0, infoText, infoTextStyle);

        /** кнопки **/
        const okButtonLabel = getLocalizedText('yes');
        const okButton = builder.buttonRed(okButtonLabel, () => {
            closeModal();
            onConfirm();
            /** событие передается в сцену текущую то есть открытую **/
            // parentSceneEvents.emit('onGameOverNewGameClick')
        }, {
            width: 330
        });

        const cancelButtonLabel = getLocalizedText('no');
        const cancelButton = builder.buttonGreen(cancelButtonLabel, () => {
            closeModal();
            /** событие передается в сцену текущую то есть открытую **/
            // parentSceneEvents.emit('onGameOverExitClick')
            onCancel?.();
        }, {
            width: 330
        });

        const buttonGroup = layoutChain({
            children: [cancelButton, okButton],
            alignToAnchor: AlignMethod.CENTER_Y,
            alignToNext: AlignMethod.RIGHT_TO,
            nextOffsetX: 30
        })

        /** макет **/
        makeAlign(align => {
            align.anchor(bg);
            align.centerX(title).topIn(title, 25)
            align.centerX(info).topIn(info, 115)
            align.centerX(buttonGroup).bottomIn(buttonGroup, -30)
        })

        container.add([
            bg, okButton, cancelButton, title, info
        ])
        return container;
    }
}
