import { Align } from "@kvisaz/phaser-sugar";
import { ViewElementBuilder } from "../../../../../assets";
import { SceneEvents } from "../../../../../common";
import { ISpiderGameUiEvents, SpiderCardTheme } from "../../events";

interface IProps {
  scene: Phaser.Scene;
}

const THEMES: SpiderCardTheme[] = ["chibi", "classic"];
const FONT_SIZE_PX = 20;
const VALUE_TEXT_FONT_SIZE = "24px";
const VALUE_TEXT_COLOR = "#ffffff";
const VALUE_TEXT_OFFSET = 6;

export function getSpiderCardThemeButton(props: IProps): Phaser.GameObjects.Container {
  const align = new Align();
  const sceneEvents = new SceneEvents<ISpiderGameUiEvents>({ scene: props.scene });
  const builder = new ViewElementBuilder(props.scene);

  let currentThemeIndex = 0;
  const getCurrentTheme = (): SpiderCardTheme => THEMES[currentThemeIndex];
  const incThemeIndex = (): void => {
    currentThemeIndex += 1;
    if (currentThemeIndex >= THEMES.length) {
      currentThemeIndex = 0;
    }
  };

  const valueText = builder.textMain(getCurrentTheme(), {
    color: VALUE_TEXT_COLOR,
    fontSize: VALUE_TEXT_FONT_SIZE,
  });

  const button = builder.buttonSecondary("Стиль карт", () => {
    incThemeIndex();
    const theme = getCurrentTheme();
    sceneEvents.emit("cardThemeFaceChange", { faceAssetName: theme });
    valueText.setText(theme);
  }, {
    fontSizePx: FONT_SIZE_PX,
    paddingY: 5,
  });

  const container = props.scene.add.container(0, 0, [button, valueText]);
  align.anchor(button).bottomTo(valueText, VALUE_TEXT_OFFSET).centerX(valueText);

  return container;
}
