import {SceneEvents, ThemedSpiderCard} from "../../../common";
import {GamePlayCardTheme} from '../../../logic';
import {IGamePlayCardEvents} from "./events";
import {
    createGamePlayCardDimmedImage,
    getGamePlayCardBackTheme,
    getGamePlayCardDefaultBackTheme,
    getGamePlayCardFaceImageMap,
} from "./themeMapping";
import {IGamePlayCardProps} from "./types";

/**
 * Как выбирается face-ассет для карты (value + suit):
 * 1) `GamePlayCard` передает в `ThemedSpiderCard` готовый `faceImageMap` из `getGamePlayCardFaceImageMap(theme)`.
 * 2) В `ThemedSpiderCard` ключ строится как `${suitPrefix}${valueShort}`:
 *    - масть: `heart | diamond | club | spade`
 *    - значения: `ace -> A`, `king -> K`, `queen -> Q`, `jack -> J`, остальные как есть (`10..2`).
 *    Примеры ключей: `heartA`, `diamond10`, `spadeQ`.
 * 3) Этот ключ ищется в `faceImageMap` и по нему берутся `url/frameName` нужного кадра атласа.
 *
 * Источник `faceImageMap`:
 * - `chibi`: прямой map `cardChibi01AutoAssetsConst`.
 * - `classic`: прямой map `cardClassic01AutoAssetsConst`.
 */
export class GamePlayCard extends ThemedSpiderCard {
    constructor(props: IGamePlayCardProps) {
        const theme = props.theme ?? GamePlayCardTheme.chibi;

        super({
            scene: props.scene,
            value: props.value,
            suit: props.suit,
            initStackId: props.initStackId,
            initSide: props.initSide,
            faceImageMap: getGamePlayCardFaceImageMap(theme),
            backTheme: getGamePlayCardDefaultBackTheme(),
            dimmedImage: createGamePlayCardDimmedImage(props.scene),
        });

        this.subscribe();
    }

    private subscribe(): void {
        const events = new SceneEvents<IGamePlayCardEvents>({scene: this.scene, autoUnSub: this});

        events.on("cardThemeFaceChange", (data) => {
            this.setFaceTheme(getGamePlayCardFaceImageMap(data.faceAssetName));
        });

        events.on("cardThemeBackChange", (data) => {
            this.setBackTheme(getGamePlayCardBackTheme(data.backAssetKey));
        });
    }
}
