import {LayoutUtils, SceneEvents} from "../../../common";
import {GameServiceProvider} from "../../../services";
import type {ThemeBackground} from "../../../config.themes";
import {assetsViewsAutoAssets} from "../assets-views-assets";
import {createTextView, makeContainerInteractive, setLeftTop} from "../utils";
import {assetsViewsTexts} from "./assets-views.text";
import {makeAlign} from '@kvisaz/phaser-sugar';
import {ButtonEvents} from "../addButtonViewInteractivity";

const BG_THUMBS_IN_ROW = 4;
const BG_THUMB_GAP = 10;
const BG_THUMB_WIDTH = 360;
const BG_THUMB_HEIGHT = 202;
const BG_THUMB_ROW_STEP = BG_THUMB_HEIGHT + BG_THUMB_GAP;
const BG_THUMB_COL_STEP = BG_THUMB_WIDTH + BG_THUMB_GAP;
const BG_THUMB_SELECT_LABEL_LEFT = 242;
const BG_THUMB_SELECT_LABEL_TOP = 160;
const BG_THUMB_SELECTED_CHECK_LEFT = 291;
const BG_THUMB_SELECTED_CHECK_TOP = 140;

export interface ICreateBgShopContentProps {
    scene: Phaser.Scene;
    backgrounds: ThemeBackground[];
}

interface ICreateBgShopContentEvents {
    setSceneBg: { url: string; fallbackUrl?: string };
    buySceneBg: { id: string; price: number };
}

interface ICreateBgThumbProps {
    scene: Phaser.Scene;
    background: ThemeBackground;
    isSelected: boolean;
    onSelect: (thumb: BgThumb) => void;
}

interface ICreateBgThumbPriceProps {
    scene: Phaser.Scene;
    price: number;
}

interface ICreateSelectLabelProps {
    scene: Phaser.Scene;
}

export function createBgShopContent(props: ICreateBgShopContentProps): Phaser.GameObjects.Container {
    const {scene, backgrounds} = props;
    const playerData = GameServiceProvider.get().getPlayerData();
    const selectedUrl = playerData.spider.gameBackground?.backgroundUrl ?? backgrounds[0]?.imageUrl.url;
    const content = new Phaser.GameObjects.Container(scene, 0, 0);
    const thumbs: BgThumb[] = [];

    backgrounds.forEach((background) => {
        thumbs.push(
            new BgThumb({
                scene,
                background,
                isSelected: background.imageUrl.url === selectedUrl,
                onSelect: (selectedThumb) => {
                    thumbs.forEach((thumb) => thumb.setSelected(thumb === selectedThumb));
                },
            }),
        );
    });

    content.add(thumbs);
    LayoutUtils.makeGridByRow(thumbs, BG_THUMBS_IN_ROW, BG_THUMB_COL_STEP, BG_THUMB_ROW_STEP);

    return content;
}

export class BgThumb extends Phaser.GameObjects.Container {
    private readonly sceneEvents: SceneEvents<ICreateBgShopContentEvents>;
    private readonly selectedFrame: Phaser.GameObjects.Image;
    private readonly selectedCheck: Phaser.GameObjects.Image;
    private readonly selectLabel?: BgThumbSelectLabel;
    private readonly isBought: boolean;
    private isSelected = false;

    constructor(private readonly props: ICreateBgThumbProps) {
        super(props.scene, 0, 0);

        this.name = props.background.id;
        this.isBought = props.background.price === 0;
        this.sceneEvents = new SceneEvents<ICreateBgShopContentEvents>({scene: props.scene, autoUnSub: this});

        const thumb = createBgThumb({scene: props.scene, background: props.background});
        this.add(thumb);

        if (this.isBought) {
            const selectLabel = new BgThumbSelectLabel(props);
            makeAlign(align => align.anchor(thumb).bottomIn(selectLabel, -5).rightIn(selectLabel, -5));
            this.add(selectLabel);
            this.selectLabel = selectLabel;
        } else {
            const price = new BgThumbPrice({scene: props.scene, price: props.background.price});
            makeAlign(align => align.anchor(thumb).bottomIn(price, -5).rightIn(price, -5));
            this.add(price);
        }

        this.selectedFrame = createSelectedFrame(props.scene);
        this.selectedCheck = createSelectedCheck(props.scene);
        this.add([this.selectedFrame, this.selectedCheck]);
        this.setSelected(props.isSelected);

        makeContainerInteractive(this);
        this.on(Phaser.Input.Events.POINTER_OVER, () => this.handleHover());
        this.on(Phaser.Input.Events.POINTER_DOWN, () => this.handleClick());
    }

    setSelected(isSelected: boolean): void {
        this.isSelected = isSelected;
        this.selectedFrame.setVisible(isSelected);
        this.selectedCheck.setVisible(isSelected);
        this.selectLabel?.setVisible(!isSelected);
    }

    private handleHover(): void {
        if (this.isSelected) {
            return;
        }

        this.scene.events.emit(ButtonEvents.onHover, {gameObjectName: this.name});
    }

    private handleClick(): void {
        if (this.isSelected) {
            return;
        }

        this.scene.events.emit(ButtonEvents.onClick, {gameObjectName: this.name});

        if (!this.isBought) {
            this.sceneEvents.emit("buySceneBg", {
                id: this.props.background.id,
                price: this.props.background.price,
            });
            return;
        }

        this.sceneEvents.emit("setSceneBg", {
            url: this.props.background.imageUrl.url,
        });
        this.props.onSelect(this);
    }
}

export class BgThumbPrice extends Phaser.GameObjects.Container {
    constructor(props: ICreateBgThumbPriceProps) {
        super(props.scene, BG_THUMB_SELECT_LABEL_LEFT, BG_THUMB_SELECT_LABEL_TOP);

        const width = 140;
        const height = 36;
        const fontSize = '32px';


        const bg = props.scene.add.nineslice(
            0,
            0,
            assetsViewsAutoAssets.bgshopmoneycounterNine14.url,
            assetsViewsAutoAssets.bgshopmoneycounterNine14.frameName,
            width,
            height,
            14,
            14,
            14,
            14,
        );

        const textData = assetsViewsTexts["text.BgShopMoneyCounter"];
        const priceText = props.scene.add.text(0, 0, String(props.price), {
            ...textData.style,
            fontSize
        });
        priceText.name = textData.name ?? '';

        const coin = new Phaser.GameObjects.Image(
            props.scene,
            0,
            0,
            assetsViewsAutoAssets.coin40.url,
            assetsViewsAutoAssets.coin40.frameName,
        );
        coin.name = assetsViewsAutoAssets.coin40.name;

        makeAlign(align => {
            align.anchor(bg).centerY(coin).rightIn(coin, coin.width / 2);
            align.anchor(coin).centerY(priceText).leftTo(priceText, -5);
        })

        this.add([bg, priceText, coin]);
        this.setSize(119, 42);
    }
}

export class BgThumbSelectLabel extends Phaser.GameObjects.Container {
    constructor(props: ICreateSelectLabelProps) {
        super(props.scene, BG_THUMB_SELECT_LABEL_LEFT, BG_THUMB_SELECT_LABEL_TOP);

        const width = 150;
        const height = 46;

        const bg = props.scene.add.nineslice(
            0,
            0,
            assetsViewsAutoAssets.btstyleshopselectSelectNine15.url,
            assetsViewsAutoAssets.btstyleshopselectSelectNine15.frameName,
            width,
            height,
            15,
            15,
            15,
            15,
        );
        setLeftTop(bg, 0, 0);

        const text = createTextView(props.scene, assetsViewsTexts.textBtStyleShopSelect, {
            style: {
                fontSize: '32px',
            },
        });

        makeAlign(align => align.anchor(bg).center(text));

        this.add([bg, text]);
    }
}

export function createBgThumb(props: Pick<ICreateBgThumbProps, "scene" | "background">): Phaser.GameObjects.Image {
    const {scene, background} = props;
    const thumb = new Phaser.GameObjects.Image(scene, 0, 0, background.thumb.url, background.thumb.frameName);

    thumb.name = background.id;
    thumb.setDisplaySize(BG_THUMB_WIDTH, BG_THUMB_HEIGHT);
    setLeftTop(thumb, 0, 0);

    return thumb;
}

function createSelectedFrame(scene: Phaser.Scene): Phaser.GameObjects.Image {
    const frame = new Phaser.GameObjects.Image(
        scene,
        0,
        0,
        assetsViewsAutoAssets.bgPrevSelected.url,
        assetsViewsAutoAssets.bgPrevSelected.frameName,
    );

    frame.name = assetsViewsAutoAssets.bgPrevSelected.name;
    frame.setDisplaySize(BG_THUMB_WIDTH, BG_THUMB_HEIGHT);
    setLeftTop(frame, 0, 0);

    return frame;
}

function createSelectedCheck(scene: Phaser.Scene): Phaser.GameObjects.Image {
    const check = new Phaser.GameObjects.Image(
        scene,
        0,
        0,
        assetsViewsAutoAssets.iconCheckmark64.url,
        assetsViewsAutoAssets.iconCheckmark64.frameName,
    );

    check.name = assetsViewsAutoAssets.iconCheckmark64.name;
    setLeftTop(check, BG_THUMB_SELECTED_CHECK_LEFT, BG_THUMB_SELECTED_CHECK_TOP);

    return check;
}
