import { IApiShopItem, ILogicShopItem, IShopCatalog } from "../types";

export function api2logicItem(
  item: IApiShopItem,
  inAppItems: IShopCatalog["inApp"],
): ILogicShopItem | undefined {
  const itemConfig = inAppItems[item.id];
  if (!itemConfig) return;

  /** проверенный ID **/
  return {
    id: item.id,
    price: item.price,
    currency: item.currency,
    rewardAdPrice: false,
    shopPack: itemConfig.shopPack,
  };
}
