interface IGoldShopData {
    scene: Phaser.Scene;
    reward?: { coins: number };
    shopItems?: { coins: number; id: string; priceString: string; }[];
}

export function createViewGoldShop({ scene, reward, shopItems }: IGoldShopData): Phaser.GameObjects.Container {
    const view = createContainerFromViewData(scene, viewGoldShopData);
    const items: Container[] = [];

    /*** итемы **/

    if (reward) {
        const viewGoldShopItemReward = buildViewGoldShopItemReward(scene, reward);
        setLeftTop(
            viewGoldShopItemReward,
            viewGoldShopData.children.viewGoldShopItemReward.x - viewGoldShopData.width / 2,
            viewGoldShopData.children.viewGoldShopItemReward.y - viewGoldShopData.height / 2,
        );
        items.push(viewGoldShopItemReward);
    }

    const [smallItem, midItem, bigItem] = shopItems ?? [];

    if (smallItem) {
        const viewGoldShopItemSmall = buildViewGoldShopItemSmall(scene, smallItem);
        setLeftTop(
            viewGoldShopItemSmall,
            viewGoldShopData.children.viewGoldShopItemSmall.x - viewGoldShopData.width / 2,
            viewGoldShopData.children.viewGoldShopItemSmall.y - viewGoldShopData.height / 2,
        );
        items.push(viewGoldShopItemSmall);
    }

    if (midItem) {
        const viewGoldShopItemMid = buildViewGoldShopItemMid(scene, midItem);
        setLeftTop(
            viewGoldShopItemMid,
            viewGoldShopData.children.viewGoldShopItemMid.x - viewGoldShopData.width / 2,
            viewGoldShopData.children.viewGoldShopItemMid.y - viewGoldShopData.height / 2,
        );
        items.push(viewGoldShopItemMid);
    }

    if (bigItem) {
        const viewGoldShopItemBig = buildViewGoldShopItemBig(scene, bigItem);
        setLeftTop(
            viewGoldShopItemBig,
            viewGoldShopData.children.viewGoldShopItemBig.x - viewGoldShopData.width / 2,
            viewGoldShopData.children.viewGoldShopItemBig.y - viewGoldShopData.height / 2,
        );
        items.push(viewGoldShopItemBig);
    }

    /** адаптив **/
    const padding = 30;
    const paddingTop = padding;
    const paddingBottom = 5;
    const itemGap = 20;
    const itemTopIn = 100;

    const childrenRow = layoutChain({
        children: items,
        alignToNext: AlignMethod.RIGHT_TO,
        nextOffsetX: itemGap,
        alignToAnchor: AlignMethod.CENTER_Y,
        });
    const childrenBounds = childrenRow.getBounds();


    const nineAsset = viewGoldShopData.children['ui.dialog.bg.light.nine.40'].asset;
    const targetWidth = childrenBounds.width + padding * 2;
    const targetHeight = childrenBounds.height + paddingTop + paddingBottom + itemTopIn;
    const uiDialogBgLightNine40 = new Phaser.GameObjects.NineSlice(
        scene,
        0,
        0,
        nineAsset.url,
        nineAsset.frameName,
        targetWidth,
        targetHeight,
        nineAsset.ninePadding,
        nineAsset.ninePadding,
        nineAsset.ninePadding,
        nineAsset.ninePadding,
    );
    setLeftTop(
        uiDialogBgLightNine40,
        viewGoldShopData.children['ui.dialog.bg.light.nine.40'].x - viewGoldShopData.width / 2,
        viewGoldShopData.children['ui.dialog.bg.light.nine.40'].y - viewGoldShopData.height / 2,
    );


    const textGoldShopTitle = createTextChild(scene, viewGoldShopData.children.textGoldShopTitle);
    setLeftTop(
        textGoldShopTitle,
        viewGoldShopData.children.textGoldShopTitle.x - viewGoldShopData.width / 2,
        viewGoldShopData.children.textGoldShopTitle.y - viewGoldShopData.height / 2,
    );


    const buttonBack = createButtonBack(scene);
    setLeftTop(
        buttonBack,
        viewGoldShopData.children.buttonBack.x - viewGoldShopData.width / 2,
        viewGoldShopData.children.buttonBack.y - viewGoldShopData.height / 2,
    );

    makeAlign(align => {
        align.anchor(uiDialogBgLightNine40).centerX(textGoldShopTitle).topIn(textGoldShopTitle, 25);
        align.anchor(uiDialogBgLightNine40).rightIn(buttonBack, -20).topIn(buttonBack, 10);
        align.anchor(uiDialogBgLightNine40).centerX(childrenRow).topIn(childrenRow, itemTopIn);
    })
    centerX(uiDialogBgLightNine40, textGoldShopTitle);


    view.add(uiDialogBgLightNine40);
    view.add(textGoldShopTitle);
    view.add(buttonBack);
    view.add(items);


    return view;
}

/**
 * Собирает вложенный view только из его direct children.
 * Родительский builder вызывает эту функцию и не разворачивает внутренности сам.
 */
function buildViewGoldShopItemReward(scene: Phaser.Scene, reward: { coins: number }): Phaser.GameObjects.Container {
    const data = viewGoldShopData.children.viewGoldShopItemReward;
    const view = createContainerFromViewData(scene, data);

    const bgGoldShopItemNine40 = createAssetChild(scene, data.children['bgGoldShopItem.nine.40']);
    setLeftTop(
        bgGoldShopItemNine40,
        data.children['bgGoldShopItem.nine.40'].x - data.width / 2,
        data.children['bgGoldShopItem.nine.40'].y - data.height / 2,
    );
    view.add(bgGoldShopItemNine40);

    const buttonGoldShopItemReward = buildButtonGoldShopItemReward(scene);
    setLeftTop(
        buttonGoldShopItemReward,
        data.children.buttonGoldShopItemReward.x - data.width / 2,
        data.children.buttonGoldShopItemReward.y - data.height / 2,
    );
    view.add(buttonGoldShopItemReward);

    const iconPacketGold = createAssetChild(scene, data.children['icon.packet_gold']);
    setLeftTop(
        iconPacketGold,
        data.children['icon.packet_gold'].x - data.width / 2,
        data.children['icon.packet_gold'].y - data.height / 2,
    );
    view.add(iconPacketGold);

    const textGoldShopItemRewardTitle = createTextChild(scene, data.children.textGoldShopItemRewardTitle);
    setLeftTop(
        textGoldShopItemRewardTitle,
        data.children.textGoldShopItemRewardTitle.x - data.width / 2,
        data.children.textGoldShopItemRewardTitle.y - data.height / 2,
    );
    view.add(textGoldShopItemRewardTitle);

    const viewGoldShopItemSmallValue = buildViewGoldShopItemSmallValue(scene, reward.coins);
    setLeftTop(
        viewGoldShopItemSmallValue,
        data.children.viewGoldShopItemSmallValue.x - data.width / 2,
        data.children.viewGoldShopItemSmallValue.y - data.height / 2,
    );
    view.add(viewGoldShopItemSmallValue);

    centerX(bgGoldShopItemNine40, buttonGoldShopItemReward);
    centerX(bgGoldShopItemNine40, iconPacketGold);
    centerX(bgGoldShopItemNine40, textGoldShopItemRewardTitle);
    centerX(bgGoldShopItemNine40, viewGoldShopItemSmallValue);


    return view;
}

