interface IParentSceneControlProps {
  parentScene: Phaser.Scene;
}

export function pauseParentSceneAudio(props: IParentSceneControlProps): void {
  props.parentScene.sound.pauseAll();
}

export function pauseParentSceneForAd(props: IParentSceneControlProps): void {
  pauseParentSceneAudio(props);
  props.parentScene.scene.pause();
}

export function resumeParentSceneAfterAd(props: IParentSceneControlProps): void {
  props.parentScene.sound.resumeAll();
  props.parentScene.scene.resume();
}
